# Generated by build.py from recipe.yml for recipe imap-share-a-folder-between-mailboxes. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'rota.eml'), "From: ann@example.com`r`nTo: team@example.com`r`nSubject: On-call rota for December`r`n`r`nBob takes the first week.`r`n")
$server0 = Start-Process surl -ArgumentList '--mail-domain', 'example.com', '--mailbox', 'ann@example.com:annpass', '--mailbox', 'bob@example.com:bobpass', '--mailbox', 'carol@example.com:carolpass', '--group', 'oncall=bob@example.com,carol@example.com', '--shared-folder', 'team=ann@example.com,bob@example.com', '--shared-folder', 'ops=@oncall', 'imap://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS -u ann@example.com:annpass -T rota.eml imap://127.0.0.1:8080/Shared/team --next -sS -u bob@example.com:bobpass "imap://127.0.0.1:8080/Shared/team;UID=1" } finally { Stop-Process $server0 }
